class Solution:
    def asciiPalindrome(self, s: str) -> bool:
        t = ''.join(format(ord(c), '08b') for c in s)
        l, r = 0, len(t) - 1
        while l < r:
            if t[l] != t[r]:
                return False
            l += 1
            r -= 1
        return True

