class Solution {
public:
    bool asciiPalindrome(string s) {
        string t;
        for (char c : s) {
            for (int b = 7; b >= 0; b--) t += ((c >> b) & 1) ? '1' : '0';
        }
        int l = 0, r = t.size() - 1;
        while (l < r) {
            if (t[l] != t[r]) return false;
            l++; r--;
        }
        return true;
    }
};

