        StringBuilder t = new StringBuilder();
        for (char c : s.toCharArray()) {
            for (int b = 7; b >= 0; b--) t.append(((c >> b) & 1) == 1 ? '1' : '0');
        }
        String str = t.toString();
        int l = 0, r = str.length() - 1;
        while (l < r) {
            if (str.charAt(l) != str.charAt(r)) return false;
            l++; r--;
        }
        return true;
    }
}

