class Solution:
    def asciiPalindrome(self, s: str) -> bool:
        L = 8 * len(s)
        def bit(p):
            return (ord(s[p // 8]) >> (7 - p % 8)) & 1
        for p in range(L // 2):
            if bit(p) != bit(L - 1 - p):
                return False
        return True

