class Solution {
    public boolean asciiPalindrome(String s) {
        int L = 8 * s.length();
        for (int p = 0; p < L / 2; p++) {
            int a = (s.charAt(p / 8) >> (7 - p % 8)) & 1;
            int b = (s.charAt((L - 1 - p) / 8) >> (7 - (L - 1 - p) % 8)) & 1;
            if (a != b) return false;
        }
        return true;
    }
}

